fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // Preconditions (per problem statement):
    // - v is sorted in nondecreasing order
    // - k appears at least once in v
    // We implement a standard lower_bound-style binary search.

    let mut lo: usize = 0;
    let mut hi: usize = v.len(); // exclusive

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let val = v[mid];

        if val < k {
            lo = mid + 1;
        } else {
            // val >= k
            hi = mid;
        }
    }

    // With the assumption that k occurs in v, lo is in-bounds and v[lo] == k.
    // (lo can only be v.len() if k is greater than all elements, which cannot happen.)
    lo
}